import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const _=JSON.parse('{"title":"峰值检测器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/peak_detector/index.md","filePath":"v0.3.0-alpha/modules/peak_detector/index.md"}'),r={name:"v0.3.0-alpha/modules/peak_detector/index.md"};function l(c,e,n,s,h,i){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="峰值检测器" tabindex="-1">峰值检测器 <a class="header-anchor" href="#峰值检测器" aria-label="Permalink to &quot;峰值检测器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>peak_detector</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>从相关帧中寻找唯一的最大绝对值，输出它所在的有符号 lag、保留符号的相关值，以及用真实原始采样率换算出的秒数。它为“样本数怎样变成传播时间”提供中间步骤，不给出目标识别或检测置信度。</p><p>例如 +6 和 −6 的绝对值都是 6；判断峰位置时比较大小 6，输出相关值时仍分别保留 +6 或 −6。两个位置同时达到最大绝对值则没有唯一峰，不能任意挑一个。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>相关器.correlation → 峰值检测器.correlation</code>，再把 <code>delay_s</code> 直接交给测距器。<code>lag_samples</code>、<code>peak_value</code> 和 <code>delay_s</code> 可分别捕获，核对“几步”“乘加值”“几秒”。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>correlation</code>（完整相关帧）</td><td><code>numeric_f64</code></td><td>原始相关值；vlen=127</td></tr><tr><td>输出</td><td><code>lag_samples</code>（有符号滞后）</td><td><code>numeric_f64</code></td><td>样本；vlen=1</td></tr><tr><td>输出</td><td><code>peak_value</code>（有符号峰值）</td><td><code>numeric_f64</code></td><td>原始相关值；vlen=1</td></tr><tr><td>输出</td><td><code>delay_s</code>（延迟）</td><td><code>numeric_f64</code></td><td>s；vlen=1</td></tr></tbody></table><p>首版只接受相关器直接输出。N、分量形状和 lag 轴必须一致，轴上保存原始 Fs。普通向量即使长度相同也不能接入；相关器与峰值检测器之间不能插入普通增益或加法模块，因为这些模块暂不传播 lag 轴。不要通过手填单位或变量名绕过来源约束。</p><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>frame_length</code> 与上游相关器的 N 一致。<code>min_abs_peak</code> 比较的是相关结果的绝对值，且必须<strong>严格高于</strong>阈值；等于阈值也不通过。原始相关会随输入幅度和窗口内容变化，不能把阈值解释成百分比。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>非重叠窗口点数 N<br><code>frame_length</code></td><td><code>64</code></td><td>范围 8 至 512</td><td>重新准备</td></tr><tr><td>最小绝对峰值（须严格超过）<br><code>min_abs_peak</code></td><td><code>0</code></td><td>范围 0 至 3.4028234663852886e+38</td><td>重新准备</td></tr></tbody></table><p>精确默认、范围及标签见上方目录导出表。选出峰后按 <code>delay_s=lag_samples/原始 Fs</code> 换算；分母是相关器输入采样率，不是相关帧率。原始 Fs 尚未知时，不能补造一个速率生成秒数。</p><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。帧长调整需与相关器保持一致并重新准备。重准备清除此前状态，旧峰与旧缓存不能证明新参数已经执行。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="把延迟换成传播距离" tabindex="-1">把延迟换成传播距离 <a class="header-anchor" href="#把延迟换成传播距离" aria-label="Permalink to &quot;把延迟换成传播距离&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/03-delay-to-distance.cnsproj" download>下载 03-delay-to-distance.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 64 item，工程不保存样本。</p><p>把延迟换成传播距离</p><ul><li>lag=2 → 0.002 s → 0.34 m，采用 340 m/s 往返传播教学模型；仅把延时改为 3 后为 0.51 m。</li></ul><p><a href="./../../learn/02-find-delay/">相关找延迟</a>先在完整 N=8 的相关图上手工读峰：参考峰位于 +2 sample，相关值为 +6。<a href="./../../learn/03-delay-to-distance/">延迟换距离</a>才加入本模块，用原始 Fs=1000 sample/s 自动换算出 <code>delay_s=0.002 s</code>，再计算米值。相应工程已通过本线软件验证。</p><p>相关父向量在单独观察器以单路“相关值—滞后”图读取；三个标量输出可独立核对。不要把相关向量中相邻 lag 看成相邻时间点，也不要把峰值符号改成正数后再记录。</p><h2 id="常见问题与失败边界" tabindex="-1">常见问题与失败边界 <a class="header-anchor" href="#常见问题与失败边界" aria-label="Permalink to &quot;常见问题与失败边界&quot;">​</a></h2><p><strong>静默窗口或两个并列绝对峰怎么办？</strong> 最大绝对值不高于阈值、或最大值并列时，任务失败并给出位置说明，不伪造一个峰。相关器仍保留真实相关结果；含本模块的任务不能以“相关帧算出来了”冒充全链成功。</p><p><strong>负峰会产生负距离吗？</strong> 峰值符号与 lag 符号各有含义。rx 反号可以保持 lag=+2 而输出峰值 −6；delay_s 仍可为正。负 lag 则产生负延迟，后接测距器会按负延迟规则失败。</p><p><strong>零 lag 是无效占位吗？</strong> 不是。合法的唯一零 lag 可输出 0 s，进而得到 0 m；不可把失败也写成零混在一起。</p><p><strong>失败后为什么还有数值？</strong> 保留最后有效数据和任务失败状态，不再产生新的有效检测结果。不要把旧点当成新结果，也不能给无峰情况补一个零。</p><p><strong>每帧都有唯一峰，能证明存在目标吗？</strong> 不能。它只说明该窗口的算术最大值唯一。周期重复、截断及跨窗歧义仍须结合真实输入解释。</p><p><a href="./../correlator/">相关器</a> · <a href="./../range_estimator/">测距器</a> · <a href="./../../learn/">学习路径</a></p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/03-delay-to-distance/">12 延迟换距离</a></li></ul>',35)])])}const m=a(r,[["render",l]]);export{_ as __pageData,m as default};
